contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params: lock time for Put, amount of wei to send with Put
    function run(uint putLock, uint putVal) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (putVal)); require(putVal <= 1000000000000000000000000000000);
        // ensure this test contract has enough Ether to send to c
        require(address(this).balance >= putVal);

        // initialize C so Put can call LogFile and no reverts from uninitialized guards
        c.SetMinSum(0); if (__ESBMC_reverted()) return;
        c.SetLogFile(address(0)); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        // read contract balance before
        uint beforeContractBal = address(c).balance;

        // perform Put sending Ether; catch revert
        bool reverted;
        c.Put{value: putVal}(putLock); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterContractBal = address(c).balance;

        // If Put succeeded then contract balance increased by exactly putVal.
        // If Put reverted then contract balance unchanged.
        assert( reverted ? (afterContractBal == beforeContractBal) : (afterContractBal == beforeContractBal + putVal) );
    }

    receive() external payable {}
}

