// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 putLock, uint256 putVal) internal {
        putVal = bound(putVal, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= putVal);
        try c.SetMinSum(0) {} catch { return; }
        try c.SetLogFile(address(0)) {} catch { return; }
        try c.Initialized() {} catch { return; }
        uint beforeContractBal = address(c).balance;
        bool reverted;
        try c.Put{value: putVal}(putLock) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterContractBal = address(c).balance;
        assertTrue(reverted ? (afterContractBal == beforeContractBal) : (afterContractBal == beforeContractBal + putVal));
    }

    function testFuzz_run(uint256 putLock, uint256 putVal) public {
        _run(putLock, putVal);
    }

    receive() external payable {}
}
